data: {"complete": true, "translated_text": "<div class=\"title-page-contributor-primary-block\" id=\"uncategorized\">\n<div class=\"heading\" id=\"uncategorized-heading\">\n<div class=\"heading-contents2\">\n<div class=\"title-page-contributor-primary-block\">\n<div class=\"element-number-block\">\n</div>\n<div class=\"title-page-contributor-primary-block\">\n<h1 class=\"title\" id=\"calibre_pb_0\">Es ist vorbei, Yo</h1>\n</div>\n</div>\n</div>\n</div>\n<div class=\"title-page-contributor-primary-block\" id=\"uncategorized-text\">\n<p class=\"first3\"><b class=\"calibre2\">Neuer Erfolg! Du hast ein Buch gelesen!</b></p>\n<p class=\"subsq\"><b class=\"calibre2\">Du hast es geschafft, das erste <i class=\"calibre1\">Dungeon Crawler Carl</i> Buch zu lesen, ohne es gegen die Wand zu werfen!</b></p>\n<p class=\"subsq\"><b class=\"calibre2\"><i class=\"calibre1\">Belohnung</i>: Du musst bis Januar 2021 warten, bevor du das nächste lesen kannst.</b></p>\n<p class=\"subsq\"><b class=\"calibre2\">Die gute Nachricht ist, das nächste Buch hat Clowns und tote Prostituierte.</b></p>\n<p class=\"implicit-break\"></p>\n<p class=\"first3\"><i class=\"calibre1\">Carls Weltuntergangsszenario</i> wird im Januar 2021 verfügbar sein. Mach dir keine Sorgen. Es ist schon geschrieben und bereit. Cheryl bearbeitet es gerade. Danke fürs Lesen. Ernsthaft. Bitte, bitte hinterlasse eine Bewertung. <span class=\"underline\">Wir leben und sterben durch unsere Bewertungen</span>, und es ist sehr wichtig. Wenn du das hier gelesen hast und es mochtest, bitte bewerte es. Es ist gegen die Regeln von Amazon, einen Preis für Bewertungen anzubieten, aber ich werde das Risiko eingehen und meine Dienste als Vater deiner Babys anbieten, wenn du eine Bewertung schreibst. Bis 2021.</p>\n</div>\n</div>"}

